#!/bin/bash
source "$(dirname "$0")/lib.sh"; NL=$'\n'; export LC_ALL=C
mbs(){ awk '/copied/{v=$(NF-1);u=$NF;if(u=="GB/s")v*=1000;if(u=="kB/s")v/=1000;printf "%d",v}'; }
S=$(date +%s.%N); python3 -c 'x=0
for i in range(5000000): x+=i*i'; E=$(date +%s.%N); CT=$(awk -v a=$S -v b=$E 'BEGIN{printf "%.2f",b-a}'); CI=$(awk -v t=$CT 'BEGIN{printf "%d",t*100}')
MM=$(dd if=/dev/zero of=/dev/null bs=1M count=3000 2>&1 | mbs); MM=${MM:-0}
F=$HOME/.dmp-bench; FREE=$(df -B1 --output=avail "$HOME" | tail -1); if [ "${FREE:-0}" -ge 1073741824 ]; then DW=$(dd if=/dev/zero of=$F bs=1M count=64 conv=fdatasync 2>&1 | mbs); else DW=0; fi; rm -f $F; DW=${DW:-0}
dev=$(lsblk -no PKNAME "$(findmnt -no SOURCE /)" 2>/dev/null | head -1); DK="type non lisible"; [ -r /sys/block/$dev/queue/rotational ] && { [ "$(cat /sys/block/$dev/queue/rotational)" = 0 ] && DK="SSD" || DK="disque dur mécanique"; }
lv(){ [ $1 -lt $2 ] && echo 0 || { [ $1 -lt $3 ] && echo 1 || echo 2; }; }
LC=$(lv $CI 80 160); LM=$([ $MM -ge 4000 ] && echo 0 || { [ $MM -ge 1500 ] && echo 1 || echo 2; }); LD=$([ $DW -ge 300 ] && echo 0 || { [ $DW -ge 100 ] && echo 1 || echo 2; })
W=$LC; [ $LM -gt $W ] && W=$LM; [ $LD -gt $W ] && W=$LD
vd(){ case $1 in 0) echo "✅ très bon";; 1) echo "🟡 correct";; *) echo "🔴 faible";; esac; }
O="⚡ Le test mesure à l'instant la vitesse de trois pièces. Il dure quelques secondes et écrit 64 Mo temporaires dans votre dossier personnel, supprimés aussitôt.${NL}${NL}1) 🧮 Calcul (processeur) : $CT s pour 5 millions d'opérations${NL}   • Pourquoi : c'est la vitesse à laquelle l'ordinateur « réfléchit ». Plus c'est court, mieux c'est.${NL}   • Repères : moins de 0,8 s très bon, de 0,8 à 1,6 s correct, plus de 1,6 s faible.${NL}   • Votre résultat : $(vd $LC)${NL}${NL}2) 🧠 Mémoire : $MM Mo/s${NL}   • Pourquoi : c'est la vitesse à laquelle les données circulent dans le bureau de travail. Elle conditionne la fluidité de tous les programmes.${NL}   • Repères : plus de 4000 Mo/s très bon, de 1500 à 4000 correct, moins de 1500 faible.${NL}   • Votre résultat : $(vd $LM)${NL}${NL}3) 💽 Disque (écriture, $DK) : $DW Mo/s${NL}   • Pourquoi : c'est la vitesse d'enregistrement des fichiers, des mises à jour et du démarrage.${NL}   • Repères : plus de 300 Mo/s très bon (SSD), de 100 à 300 correct, moins de 100 faible (disque dur mécanique ou disque occupé).${NL}   • Votre résultat : $(vd $LD)"
case $W in 0) R="Machine rapide"; X="Les trois mesures sont bonnes : processeur, mémoire et disque suivent. Refaites ce test de temps en temps : une baisse nette signale un problème (disque fatigué, programme en arrière-plan).";; 1) R="Vitesse moyenne : à surveiller"; X="Au moins une mesure est seulement correcte. Rien d'anormal pour un usage courant. Si la machine vous paraît lente, la mesure la plus faible indique la pièce à regarder.";; *) R="Vitesse faible : à améliorer"; X="Au moins une mesure est faible : c'est la pièce qui limite votre ordinateur. Le disque est le plus facile à améliorer (un SSD change tout). Relancez le test sans autre programme ouvert pour vérifier que ce n'est pas passager.";; esac
export X; j "Le test de vitesse (benchmark) est comme chronométrer un coureur : on fait faire à l'ordinateur un effort identique à chaque fois, pour savoir à quelle vitesse il va et suivre son évolution." "$O" "$R" "python3, dd (DMP uniquement)"
